describe('Coupon Code Validation Error Message', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display error message when invalid coupon code is entered', () => {
    // Intercept the coupon validation API call
    cy.intercept('POST', '/api/coupon/validate').as('validateCoupon');

    // Enter a valid coupon code
    cy.get('[data-testid="coupon-input"]').type('SUMMER20');
    cy.get('[data-testid="apply-coupon-button"]').click();

    // Wait for the API call
    cy.wait('@validateCoupon');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Coupon applied successfully');

    // Clear the coupon input
    cy.get('[data-testid="coupon-input"]').clear();

    // Enter an invalid coupon code
    cy.get('[data-testid="coupon-input"]').type('INVALIDCODE123');
    cy.get('[data-testid="apply-coupon-button"]').click();

    // Wait for the API call
    cy.wait('@validateCoupon');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid coupon code');

    // Verify error styling is applied
    cy.get('[data-testid="coupon-input"]').should('have.class', 'input-error');

    // Verify coupon input field is still focused
    cy.get('[data-testid="coupon-input"]').should('be.visible');
  });

  it('should handle empty coupon code submission and display appropriate error', () => {
    // Intercept the coupon validation API call
    cy.intercept('POST', '/api/coupon/validate').as('validateCoupon');

    // Attempt to submit without entering a coupon code
    cy.get('[data-testid="apply-coupon-button"]').click();

    // Wait for the API call
    cy.wait('@validateCoupon');

    // Verify error message for empty field is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Please enter a coupon code');

    // Verify coupon input field has validation styling
    cy.get('[data-testid="coupon-input"]').should('have.class', 'input-error');

    // Verify success message is NOT displayed
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Clear the error state by entering a valid code
    cy.get('[data-testid="coupon-input"]').clear();
    cy.get('[data-testid="coupon-input"]').type('SUMMER20');
    cy.get('[data-testid="apply-coupon-button"]').click();

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
